<span class="line"><span style="color:#ABB2BF;">|     table2|</span><span style="color:#D19A66;">31536000000</span><span style="color:#ABB2BF;">| </span><span style="color:#C678DD;">USING</span><span style="color:#ABB2BF;">|   </span><span style="color:#C678DD;">null</span><span style="color:#ABB2BF;">|    BASE </span><span style="color:#C678DD;">TABLE</span><span style="color:#ABB2BF;">|</span></span>
